package io.github.offlineglass.hook.adapters.weibo

import android.graphics.BitmapFactory
import android.util.Base64

/** Byte-for-byte copies of the bundled artwork for hosts that cannot open module assets. */
internal object WeiboEmbeddedIcons {
    fun decode(name: String) = encoded(name)?.let {
        val bytes = Base64.decode(it, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }

    private fun encoded(name: String): String? = when (name) {
        "tabbar_discover_highlighted_v2.png" -> ""
        "tabbar_discover_v2.png" -> ""
        "tabbar_home_highlighted_v2.png" -> ""
        "tabbar_home_v2.png" -> ""
        "tabbar_icon_discover_highlighted_dark_v2.png" -> ""
        "tabbar_icon_discover_normal_dark_v2.png" -> ""
        "tabbar_icon_home_highlighted_dark_v2.png" -> ""
        "tabbar_icon_home_normal_dark_v2.png" -> ""
        "tabbar_icon_message_highlighted_dark_v2.png" -> ""
        "tabbar_icon_message_normal_dark_v2.png" -> ""
        "tabbar_icon_profile_highlighted_dark_v2.webp" -> ""
        "tabbar_icon_profile_normal_dark_v2.webp" -> ""
        "tabbar_icon_video_highlighted_dark_v2.webp" -> ""
        "tabbar_icon_video_normal_dark_v2.webp" -> ""
        "tabbar_message_center_highlighted_v2.png" -> ""
        "tabbar_message_center_v2.png" -> ""
        "tabbar_profile_highlighted_v2.png" -> ""
        "tabbar_profile_v2.png" -> ""
        "tabbar_video_highlighted_v2.webp" -> ""
        "tabbar_video_v2.webp" -> ""
        else -> null
    }
}
